#!/usr/bin/env node
/**
 * Independent acceptance audit. READ-ONLY for the implementing agent: do not edit this file.
 * Usage:
 *   node scripts/audit.mjs --task 0..7     run one task's checks
 *   node scripts/audit.mjs --all           run every task
 *   node scripts/audit.mjs --gates         also run tsc / lint / tests / build / npm audit (slow)
 *   node scripts/audit.mjs --all --gates --write   writes docs/AUDIT_RESULT.txt
 * Exit code 0 only if every selected check passes. Pure Node, no dependencies.
 */
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";

const ROOT = process.cwd();
const args = process.argv.slice(2);
const wantAll = args.includes("--all");
const gates = args.includes("--gates");
const write = args.includes("--write");
const ti = args.indexOf("--task");
const only = ti >= 0 ? Number(args[ti + 1]) : null;

const IGNORE = new Set(["node_modules", ".next", ".git", "dist", "coverage", "playwright-report", "test-results", "drizzle"]);
function walk(dir, out = []) {
  if (!fs.existsSync(dir)) return out;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (IGNORE.has(e.name)) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else out.push(p);
  }
  return out;
}
const rel = (p) => path.relative(ROOT, p).split(path.sep).join("/");
const exists = (p) => fs.existsSync(path.join(ROOT, p));
const read = (p) => (exists(p) ? fs.readFileSync(path.join(ROOT, p), "utf8") : "");
const CODE = /\.(ts|tsx|js|jsx|mjs|css)$/;
const filesIn = (dirs, re = CODE) => dirs.flatMap((d) => walk(path.join(ROOT, d))).map(rel).filter((f) => re.test(f) && f !== "scripts/audit.mjs");
const SRC = () => filesIn(["src", "workers"]);
const isTest = (f) => /(\.test\.|\.spec\.|\/tests?\/|\/e2e\/|fixtures)/.test(f);
const LEGAL = /(terms|privacy|acceptable-use|clean-room-ip-policy|dmca|refund-policy)\/page\.tsx$/;

const results = [];
function check(task, name, ok, detail = "") { results.push({ task, name, ok: !!ok, detail }); }
const mustExist = (task, files) => files.forEach((f) => check(task, `exists: ${f}`, exists(f)));
const mustNotExist = (task, files) => files.forEach((f) => check(task, `removed: ${f}`, !exists(f)));
function forbid(task, label, re, files, { skipTests = false, skipLegal = false } = {}) {
  const hits = [];
  for (const f of files) {
    if (skipTests && isTest(f)) continue;
    if (skipLegal && LEGAL.test(f)) continue;
    const t = read(f);
    const m = t.match(re);
    if (m) hits.push(`${f}: ${String(m[0]).slice(0, 50)}`);
  }
  check(task, `forbidden: ${label}`, hits.length === 0, hits.slice(0, 4).join(" | ") + (hits.length > 4 ? ` (+${hits.length - 4} more)` : ""));
}
function require_(task, label, re, file) { check(task, `required: ${label} in ${file}`, re.test(read(file))); }
function importedBy(task, symbolOrPath, byFiles) {
  const ok = byFiles.some((f) => read(f).includes(symbolOrPath));
  check(task, `wired: "${symbolOrPath}" is used by ${byFiles.join(" or ")}`, ok);
}
const pkg = () => { try { return JSON.parse(read("package.json")); } catch { return {}; } };
const hasDep = (n) => { const p = pkg(); return !!({ ...p.dependencies, ...p.devDependencies })[n]; };

/* ---------- TASK 0: foundation ---------- */
function t0() {
  for (const d of ["vitest", "@playwright/test", "playwright", "bullmq", "ioredis", "@aws-sdk/client-s3", "@aws-sdk/s3-request-presigner", "undici", "fast-check", "pino", "file-type", "resend", "@axe-core/playwright"])
    check(0, `dependency: ${d}`, hasDep(d));
  check(0, "npm script test uses vitest", /vitest/.test(pkg().scripts?.test ?? ""));
  mustNotExist(0, ["test-verification.ts", "tests/security.test.ts"]);
  mustExist(0, ["vitest.config.ts", "playwright.config.ts", ".github/workflows/ci.yml", ".env.example", "docker-compose.yml"]);
  const dc = read("docker-compose.yml");
  for (const s of ["postgres", "redis", "minio"]) check(0, `compose has ${s}`, new RegExp(s, "i").test(dc));
  const env = read("src/env.ts");
  check(0, "env.ts: no default for secrets (DATA_KEY/NEXTAUTH_SECRET/FAKE_WEBHOOK_SECRET)", !/(DATA_KEY|NEXTAUTH_SECRET|FAKE_WEBHOOK_SECRET)[^\n]*\.default\(\s*["'`]/.test(env));
  check(0, "env.ts: ALLOW_RUNC not defaulting to true", !/ALLOW_RUNC[^\n]*default\(\s*["'`]?true/.test(env));
  check(0, "env.ts: production refuses PAYMENT_PROVIDER=fake and LLM_PROVIDER=fixture", /fake/.test(env) && /production/.test(env) && /superRefine|refine/.test(env));
  check(0, "env.ts: skips strict validation only during `next build` phase", /phase-production-build/.test(env));
  const layout = read("src/app/layout.tsx");
  for (const f of ["IBM_Plex_Sans", "IBM_Plex_Serif", "IBM_Plex_Mono"]) check(0, `layout loads ${f} via next/font`, new RegExp(f).test(layout) && /next\/font\/google/.test(layout));
  check(0, "layout: lang=en, no dir=rtl", /lang=["']en["']/.test(layout) && !/dir=["']rtl/.test(layout));
}

